<content>import json

baseline = {'performance_multiplier': 1.2, 'budget_overrun_pct': 200, 'schedule_delay_months': 6, 'risk_points': 9}
with open('decision_delta_matrix.json', 'r') as f:
    decisions = json.load(f)

combo = ['delivery', 'stack', 'testing']
total_delta = {'performance_multiplier': 0.0, 'budget_overrun_pct': 0, 'schedule_delay_months': 0, 'risk_points': 0}

for d in decisions:
    if d['decision_id'] in combo:
        print(f"Adding {d['decision_id']}: {d['delta']}")
        for k in total_delta:
            total_delta[k] += d['delta'][k]

print('Total delta:', total_delta)
projected = {k: baseline[k] + total_delta[k] for k in baseline}
print('Projected:', projected)
score = projected['performance_multiplier']*10 + projected['budget_overrun_pct']/10 + projected['schedule_delay_months']*5 + projected['risk_points']*3
print('Score:', score)

# Also check the other combo
print('\nChecking combo: team, governance, staffing')
combo2 = ['team', 'governance', 'staffing']
total_delta2 = {'performance_multiplier': 0.0, 'budget_overrun_pct': 0, 'schedule_delay_months': 0, 'risk_points': 0}
for d in decisions:
    if d['decision_id'] in combo2:
        print(f"Adding {d['decision_id']}: {d['delta']}")
        for k in total_delta2:
            total_delta2[k] += d['delta'][k]
print('Total delta2:', total_delta2)
projected2 = {k: baseline[k] + total_delta2[k] for k in baseline}
print('Projected2:', projected2)
score2 = projected2['performance_multiplier']*10 + projected2['budget_overrun_pct']/10 + projected2['schedule_delay_months']*5 + projected2['risk_points']*3
print('Score2:', score2)</content>
